<script setup lang="ts">import AdminLayout from '@/Layouts/AdminLayout.vue';import{Head,router}from'@inertiajs/vue3';const props=defineProps<{posts:any,filters:any}>();function moderate(post:any,action:string){const reason=action==='remove'?prompt('Moderation reason:'):'';if(action==='remove'&&!reason)return;router.post(route('admin.posts.moderate',post.id),{action,reason})}</script><template><Head title="Social posts"/><AdminLayout><h1 class="text-2xl font-bold">Social posts</h1><div class="mt-5 overflow-x-auto rounded-xl border bg-white"><table class="w-full text-sm"><thead class="bg-slate-50 text-left text-slate-500"><tr><th class="p-4">ID</th><th>Author</th><th>Type</th><th>Created</th><th>Reports</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="post in posts.data" :key="post.id" class="border-t"><td class="p-4">{{post.id}}</td><td>{{post.user?.name}}</td><td>{{post.media_count?'Media':'Text'}}</td><td>{{new Date(post.created_at).toLocaleString()}}</td><td>{{post.reports_count}}</td><td>{{post.status}}</td><td><button @click="moderate(post,post.deleted_at?'restore':'remove')" class="text-cyan-700">{{post.deleted_at?'Restore':'Remove'}}</button></td></tr></tbody></table></div></AdminLayout></template>
